syntax:
```cpp
#include <memory>

// unique_ptr: Exclusive ownership
std::unique_ptr<int> up = std::make_unique<int>(10);
// Access the managed object: *up

// shared_ptr: Shared ownership
std::shared_ptr<int> sp = std::make_shared<int>(20);
std::shared_ptr<int> sp2 = sp; // sp and sp2 share ownership
// Access the managed object: *sp or *sp2

//Custom Deleter for resources beyond raw memory
struct MyResource {
  ~MyResource() { /*Resource cleanup*/}
};

std::unique_ptr<MyResource, void(*)(MyResource*)> custom_resource(
    new MyResource(), [](MyResource* ptr){ delete ptr;});
```

code_example:
#include <iostream>
#include <memory>
void processData(std::shared_ptr<int> data) {
  if (data) {
    std::cout << "Data: " << *data << std::endl;
  }
}
int main() {
  auto sharedData = std::make_shared<int>(42);
  processData(sharedData);
  // sharedData and any copies will automatically delete the int when they go out of scope.
  std::unique_ptr<int> uniqueData = std::make_unique<int>(100);
  // uniqueData will automatically delete the int when it goes out of scope.
  return 0;
}
